package org.example.observer_pattern.spring_boot;import org.springframework.context.event.EventListener;import org.springframework.stereotype.Component;@Componentpublic class AdminDashboardNotifier {    @EventListener    public void notifyDashboard(OrderCreatedEvent event) {        System.out.println("📡 Cập nhật dashboard: đơn hàng " + event.getOrder().getId());    }}